const LP_API='/api/v1/legacy-parity';
const tokenKey='lvsp_access_token';
const E=(v:any)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const D=(v:any)=>{if(!v)return '—';const s=String(v).slice(0,10),p=s.split('-');return p.length===3?`${p[2]}/${p[1]}/${p[0]}`:s};
const V=(sel:string)=>document.querySelector(sel) as any;
function tok(){return localStorage.getItem(tokenKey)||''}
async function lpApi(path:string,opts:any={}){const h:any={'content-type':'application/json',...(opts.headers||{})};if(tok())h.authorization='Bearer '+tok();const r=await fetch(LP_API+path,{...opts,headers:h});const j=await r.json();if(!r.ok)throw new Error(j?.error?.message||`HTTP ${r.status}`);return j}
async function coreApi(path:string,opts:any={}){const h:any={'content-type':'application/json',...(opts.headers||{})};if(tok())h.authorization='Bearer '+tok();const r=await fetch('/api/v1'+path,{...opts,headers:h});const j=await r.json();if(!r.ok)throw new Error(j?.error?.message||`HTTP ${r.status}`);return j}
