function makeDialog(id:string,title:string){let d=document.querySelector('#'+id) as HTMLDialogElement;if(d)d.remove();d=document.createElement('dialog');d.id=id;d.className='lp-dialog';d.innerHTML=`<div class="lp-dialog-head"><h2>${E(title)}</h2><button class="lp-x" type="button">×</button></div><div class="lp-dialog-body"></div>`;document.body.appendChild(d);d.querySelector('.lp-x')?.addEventListener('click',()=>d.close());d.addEventListener('close',()=>setTimeout(()=>d.remove(),20));d.showModal();return d}
function ensurePrintHost(){let h=document.querySelector('#lp-print-host') as HTMLElement;if(!h){h=document.createElement('div');h.id='lp-print-host';document.body.appendChild(h)}return h}
async function printHtml(html:string){const h=ensurePrintHost();if(h.parentElement!==document.body)document.body.appendChild(h);h.innerHTML=html;const imgs=[...h.querySelectorAll('img')] as HTMLImageElement[];await Promise.all(imgs.map(img=>img.complete?Promise.resolve():new Promise<void>(resolve=>{const done=()=>resolve();img.addEventListener('load',done,{once:true});img.addEventListener('error',done,{once:true});setTimeout(done,900)})));try{await (document as any).fonts?.ready}catch{}setTimeout(()=>window.print(),120);setTimeout(()=>{h.innerHTML=''},1800)}
function dl(name:string,content:string,type='text/plain;charset=utf-8'){const b=new Blob(['\ufeff',content],{type});const u=URL.createObjectURL(b);const a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),500)}
function isoToday(){return new Date().toISOString().slice(0,10)}
function nameDate(){return new Date().toISOString().slice(0,10).replaceAll('-','')}

