function emptyMemo(){return {memoNo:'',memoSuffix:'ພສວພ',memoDate:isoToday(),placeText:'ນະຄອນຫຼວງວຽງຈັນ',organizationName:'ກົມລ້ຽງສັດ ແລະ ການປະມົງ',departmentName:'ພະແນກສັດຕະວະແພດ',recipient:'ຫົວໜ້າກົມລ້ຽງສັດ ແລະ ການປະມົງ',subjectText:'ການອອກໃບທະບຽນຢາສັດຕະວະແພດ',leadText:'',purposes:['approve'],companyAuto:true,groupByCompany:true,showLao:true,showSubRegistration:true,showPack:true,showCategory:true,staffLines:[''],signatoryNames:{sectionHead:'',veterinaryHead:'',technicalOfficer:'',deputyDirector:''},notes:'',status:'DRAFT'}}

export async function renderRegistrationMemoCenter(){ensureStyles();const root=V('#custom-page');if(!root)return;V('#page-title').textContent='ໃບກິດສຳພັນທະບຽນຢາ';V('#page-subtitle').textContent='1 ໃບກິດສຳພັນ → ຫຼາຍຕົວຢາ / ຫຼາຍໃບທະບຽນ';root.innerHTML=`<div class="lp-center"><div class="lp-hero"><div><span class="lp-kicker">REGISTRATION COVER / INTERNAL MEMO</span><h2>ໃບກິດສຳພັນສຳລັບອອກທະບຽນເປັນຊຸດ</h2><p>ເລືອກຫຼາຍທະບຽນໃນໃບດຽວ. ຕົວຢາໜຶ່ງຢູ່ແຖວດຽວ ແລະ sub-registration/ຂະໜາດບັນຈຸຈະຖືກຈັດກຸ່ມໃນແຖວນັ້ນ.</p></div><div class="lp-actions"><button class="lp-btn" id="lp-back-drug">← ກັບທະບຽນຢາ</button><button class="lp-btn primary" id="lp-new-memo">+ ສ້າງໃບກິດສຳພັນ</button><button class="lp-btn" id="lp-refresh-memos">↻ ໂຫຼດຄືນ</button></div></div><div id="lp-memo-list" class="lp-card">Loading…</div></div>`;V('#lp-back-drug').onclick=()=>{const b=document.querySelector('.nav-item[data-key=\"drug_registrations\"]') as HTMLElement|null;if(b)b.click()};V('#lp-new-memo').onclick=()=>openRegistrationBatchMemo();V('#lp-refresh-memos').onclick=()=>renderRegistrationMemoCenter();try{const r=await lpApi('/registration-memos');const list=r.data||[];V('#lp-memo-list').innerHTML=list.length?`<div class="lp-table-wrap"><table class="lp-table"><thead><tr><th>ເລກທີ</th><th>ວັນທີ</th><th>ຮຽນ</th><th>ຈຳນວນທະບຽນ</th><th>ສະຖານະ</th><th></th></tr></thead><tbody>${list.map((x:any)=>`<tr><td><b>${E(x.memoNo||'ຮ່າງ')}</b>/${E(x.memoSuffix||'')}</td><td>${D(x.memoDate)}</td><td>${E(x.recipient||'')}</td><td>${E(x.itemCount)}</td><td><span class="lp-pill">${E(x.status)}</span></td><td><button class="lp-btn lp-open-memo" data-id="${E(x.id)}">ເປີດ</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="lp-empty">ຍັງບໍ່ມີໃບກິດສຳພັນທີ່ບັນທຶກ</div>`;document.querySelectorAll('.lp-open-memo').forEach(b=>b.addEventListener('click',()=>openRegistrationBatchMemo(undefined,(b as HTMLElement).dataset.id)))}catch(e:any){V('#lp-memo-list').innerHTML=`<div class="lp-empty">${E(e.message)}</div>`}}

export async function openRegistrationBatchMemo(seedProfileId?:string,memoId?:string){ensureStyles();const d=makeDialog('lp-memo-dialog','📄 ໃບກິດສຳພັນ — ເລືອກຫຼາຍໃບທະບຽນ');const body=d.querySelector('.lp-dialog-body') as HTMLElement;body.innerHTML='<div class="lp-empty">Loading registration registry…</div>';
 try{const [cr,mr]=await Promise.all([lpApi('/registration-candidates'),memoId?lpApi('/registration-memos/'+encodeURIComponent(memoId)):Promise.resolve(null)]);let candidates=cr.data||[];let memo=mr?.data?.memo||emptyMemo();const existingItems=mr?.data?.items||[];for(const it of existingItems){let c=candidates.find((x:any)=>String(x.regulatoryProfileId)===String(it.regulatoryProfileId));if(!c){c={regulatoryProfileId:it.regulatoryProfileId,registrationNo:it.registrationNoSnapshot,tradeName:it.tradeNameSnapshot,genericName:it.genericNameSnapshot,category:it.categorySnapshot,dosageForm:it.dosageFormSnapshot,registrationHolder:it.holderSnapshot,manufacturerName:it.manufacturerSnapshot,registrationStatus:it.sourceSnapshot?.registrationStatus||'SNAPSHOT',presentations:[...(it.selectedPresentations||[])]};candidates.push(c)}else{for(const p of (it.selectedPresentations||[])){if(!(c.presentations||[]).some((z:any)=>String(z.packageId)===String(p.packageId)))(c.presentations||(c.presentations=[])).push(p)}}}const selected=new Map<string,Set<string>>();for(const it of existingItems){selected.set(String(it.regulatoryProfileId),new Set((it.selectedPresentations||[]).map((p:any)=>String(p.packageId))))}if(seedProfileId&&!selected.has(seedProfileId)){const c=candidates.find((x:any)=>String(x.regulatoryProfileId)===String(seedProfileId));selected.set(seedProfileId,new Set((c?.presentations||[]).map((p:any)=>String(p.packageId))))}
  const companies=[...new Set(candidates.map((x:any)=>x.registrationHolder||x.importer).filter(Boolean))].sort();const cats=[...new Set(candidates.map((x:any)=>x.category).filter(Boolean))].sort();const statuses=[...new Set(candidates.map((x:any)=>x.registrationStatus).filter(Boolean))].sort();
  body.innerHTML=`<div class="lp-grid"><div class="lp-stack"><div class="lp-card"><h3>1. ຂໍ້ມູນໃບກິດສຳພັນ</h3><div class="lp-form-grid"><label class="lp-field"><span>ເລກທີ</span><input id="lpm-no" value="${E(memo.memoNo||'')}"></label><label class="lp-field"><span>ອັກສອນທ້າຍ</span><input id="lpm-suffix" value="${E(memo.memoSuffix||'ພສວພ')}"></label><label class="lp-field"><span>ວັນທີ</span><input id="lpm-date" type="date" value="${E(String(memo.memoDate||isoToday()).slice(0,10))}"></label><label class="lp-field"><span>ສະຖານທີ່</span><input id="lpm-place" value="${E(memo.placeText||'ນະຄອນຫຼວງວຽງຈັນ')}"></label><label class="lp-field span2"><span>ຮຽນ</span><input id="lpm-to" value="${E(memo.recipient||'')}"></label><label class="lp-field span2"><span>ເລື່ອງ</span><input id="lpm-subject" value="${E(memo.subjectText||'')}"></label><label class="lp-field span2"><span>ຂໍ້ຄວາມນຳ (ຖ້າປ່ອຍວ່າງ ລະບົບຈະສ້າງຈາກຈຳນວນທະບຽນ/ບໍລິສັດ)</span><textarea id="lpm-lead" rows="2">${E(memo.leadText||'')}</textarea></label><div class="span2"><span class="lp-sub">ຈຸດປະສົງ</span><div class="lp-checks">${Object.entries(PURPOSES).map(([k,v])=>`<label class="lp-check"><input class="lpm-purpose" type="checkbox" value="${k}" ${(memo.purposes||[]).includes(k)?'checked':''}>${E(v)}</label>`).join('')}</div></div><div class="span2"><span class="lp-sub">ຮູບແບບ</span><div class="lp-checks"><label class="lp-check"><input id="lpm-group" type="checkbox" ${memo.groupByCompany!==false?'checked':''}>ຈັດກຸ່ມຕາມບໍລິສັດ</label><label class="lp-check"><input id="lpm-subreg" type="checkbox" ${memo.showSubRegistration!==false?'checked':''}>ສະແດງ sub-registration</label><label class="lp-check"><input id="lpm-pack" type="checkbox" ${memo.showPack!==false?'checked':''}>ສະແດງຂະໜາດບັນຈຸ</label><label class="lp-check"><input id="lpm-cat" type="checkbox" ${memo.showCategory!==false?'checked':''}>ສະແດງປະເພດຢາ</label></div></div><label class="lp-field"><span>ສະຖານະ</span><select id="lpm-status">${['DRAFT','READY','SIGNED','ARCHIVED','CANCELLED'].map(x=>`<option ${memo.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="lp-field"><span>ພະນັກງານກວດ/ສັງລວມ</span><input id="lpm-tech" value="${E(memo.signatoryNames?.technicalOfficer||'')}"></label><label class="lp-field"><span>ຫົວໜ້າພະແນກສັດຕະວະແພດ</span><input id="lpm-vethead" value="${E(memo.signatoryNames?.veterinaryHead||'')}"></label><label class="lp-field"><span>ຫົວໜ້າຂະແໜງ/ສັງລວມ</span><input id="lpm-section" value="${E(memo.signatoryNames?.sectionHead||'')}"></label><label class="lp-field span2"><span>ລາຍຊື່ຄະນະເຮັດວຽກ (1 ຊື່/1 ແຖວ)</span><textarea id="lpm-staff" rows="2">${E((memo.staffLines||[]).join('\n'))}</textarea></label></div></div>
  <div class="lp-card"><div class="lp-selection-head"><h3>2. ເລືອກທະບຽນ <span id="lpm-count" class="lp-count"></span></h3><div class="lp-actions"><button class="lp-btn" id="lpm-all" type="button">✓ ເລືອກທັງໝົດທີ່ກັ່ນຕອງ</button><button class="lp-btn" id="lpm-clear" type="button">ລ້າງ</button></div></div><div class="lp-filters"><div class="lp-filter"><input id="lpm-search" placeholder="ຄົ້ນຫາ ຊື່ຢາ / Reg No. / INN"></div><div class="lp-filter"><select id="lpm-company"><option value="">ທຸກບໍລິສັດ</option>${companies.map(x=>`<option>${E(x)}</option>`).join('')}</select></div><div class="lp-filter"><select id="lpm-category"><option value="">ທຸກປະເພດ</option>${cats.map(x=>`<option>${E(x)}</option>`).join('')}</select></div></div><div class="lp-filters" style="grid-template-columns:1fr 2fr"><div class="lp-filter"><select id="lpm-regstatus"><option value="">ທຸກສະຖານະ</option>${statuses.map(x=>`<option>${E(x)}</option>`).join('')}</select></div><div class="lp-sub">ຕິກຕົວຢາ ແລ້ວສາມາດຕິກ/ຖອນຂະໜາດບັນຈຸຍ່ອຍໄດ້. 1 ຕົວຢາ = 1 ແຖວໃນໃບ.</div></div><div id="lpm-candidates" class="lp-selection-list"></div></div><div class="lp-actions"><button class="lp-btn primary" id="lpm-save" type="button">💾 ບັນທຶກ</button><button class="lp-btn gold" id="lpm-print" type="button">🖨 Print / PDF</button><button class="lp-btn" id="lpm-word" type="button">W Word</button></div></div><div class="lp-preview-shell"><div class="lp-card"><h3>3. A4 Preview</h3><div id="lpm-preview"></div><div class="lp-print-note">Preview ອັບເດດຕາມລາຍການທີ່ເລືອກ</div></div></div></div>`;
  function memoFromForm(){return {memoNo:V('#lpm-no').value,memoSuffix:V('#lpm-suffix').value,memoDate:V('#lpm-date').value,placeText:V('#lpm-place').value,organizationName:memo.organizationName||'ກົມລ້ຽງສັດ ແລະ ການປະມົງ',departmentName:memo.departmentName||'ພະແນກສັດຕະວະແພດ',recipient:V('#lpm-to').value,subjectText:V('#lpm-subject').value,leadText:V('#lpm-lead').value,purposes:[...document.querySelectorAll('.lpm-purpose:checked')].map((x:any)=>x.value),companyAuto:true,groupByCompany:V('#lpm-group').checked,showLao:true,showSubRegistration:V('#lpm-subreg').checked,showPack:V('#lpm-pack').checked,showCategory:V('#lpm-cat').checked,staffLines:V('#lpm-staff').value.split('\n').map((x:string)=>x.trim()).filter(Boolean),signatoryNames:{technicalOfficer:V('#lpm-tech').value,veterinaryHead:V('#lpm-vethead').value,sectionHead:V('#lpm-section').value},notes:memo.notes||'',status:V('#lpm-status').value}}
  function filtered(){const q=V('#lpm-search').value.toLowerCase().trim(),co=V('#lpm-company').value,cat=V('#lpm-category').value,st=V('#lpm-regstatus').value;return candidates.filter((x:any)=>(!q||[x.registrationNo,x.tradeName,x.genericName,x.activeIngredients].join(' ').toLowerCase().includes(q))&&(!co||(x.registrationHolder||x.importer)===co)&&(!cat||x.category===cat)&&(!st||x.registrationStatus===st))}
  function renderCandidates(){const data=filtered();V('#lpm-candidates').innerHTML=data.length?data.map((x:any)=>{const id=String(x.regulatoryProfileId),on=selected.has(id),pk=selected.get(id)||new Set();return `<div class="lp-candidate" data-id="${E(id)}"><div class="lp-candidate-main"><input class="lpm-product" type="checkbox" data-id="${E(id)}" ${on?'checked':''}><label><b>${E(x.tradeName||'')}</b> <span class="lp-pill">${E(x.registrationNo||'No Reg No.')}</span><div class="lp-candidate-meta">${E(x.genericName||x.activeIngredients||'')} · ${E(x.category||'')} · ${E(x.registrationHolder||x.importer||'')}</div></label></div><div class="lp-candidate-pres">${(x.presentations||[]).length?(x.presentations||[]).map((p:any,i:number)=>`<label class="lp-pres"><input class="lpm-package" type="checkbox" data-profile="${E(id)}" data-package="${E(p.packageId)}" ${on&&pk.has(String(p.packageId))?'checked':''} ${on?'':'disabled'}><code>${E((x.registrationNo||'')+((x.presentations||[]).length>1?'-'+(p.subCode||String(i+1).padStart(2,'0')):''))}</code><span>${E(p.strengthText||'')} ${p.packDescription?'· '+E(p.packDescription):''}</span></label>`).join(''):'<span class="lp-sub">ບໍ່ມີ presentation — ຈະໃຊ້ base registration</span>'}</div></div>`}).join(''):'<div class="lp-empty">ບໍ່ພົບລາຍການ</div>';
   document.querySelectorAll('.lpm-product').forEach(el=>el.addEventListener('change',()=>{const c=el as HTMLInputElement,id=String(c.dataset.id),cand=candidates.find((x:any)=>String(x.regulatoryProfileId)===id);if(c.checked)selected.set(id,new Set((cand?.presentations||[]).map((p:any)=>String(p.packageId))));else selected.delete(id);renderCandidates();refreshPreview()}));document.querySelectorAll('.lpm-package').forEach(el=>el.addEventListener('change',()=>{const c=el as HTMLInputElement,pid=String(c.dataset.profile),pk=selected.get(pid)||new Set();if(c.checked)pk.add(String(c.dataset.package));else pk.delete(String(c.dataset.package));selected.set(pid,pk);refreshPreview()}));refreshCount()}
  function refreshCount(){let pres=0;for(const x of selected.values())pres+=x.size;V('#lpm-count').textContent=`(${selected.size} ຕົວຢາ · ${pres} presentation)`}
  function selectionItems(){return [...selected.entries()].map(([regulatoryProfileId,pks])=>({regulatoryProfileId,selectedPackageIds:[...pks]}))}
  function currentRows(){return selectionItems().map((s:any)=>{const x=candidates.find((c:any)=>String(c.regulatoryProfileId)===String(s.regulatoryProfileId));const pk=(x?.presentations||[]).filter((p:any)=>s.selectedPackageIds.includes(String(p.packageId)));return {...x,selectedPresentations:pk}}).filter(Boolean)}
  function memoHtml(){return buildMemoPaper(memoFromForm(),currentRows())}
  function refreshPreview(){refreshCount();V('#lpm-preview').innerHTML=memoHtml()}
  for(const s of ['#lpm-search','#lpm-company','#lpm-category','#lpm-regstatus'])V(s).addEventListener(s==='#lpm-search'?'input':'change',renderCandidates);for(const s of ['#lpm-no','#lpm-suffix','#lpm-date','#lpm-place','#lpm-to','#lpm-subject','#lpm-lead','#lpm-status','#lpm-tech','#lpm-vethead','#lpm-section','#lpm-staff','#lpm-group','#lpm-subreg','#lpm-pack','#lpm-cat'])V(s)?.addEventListener('input',refreshPreview);document.querySelectorAll('.lpm-purpose').forEach(x=>x.addEventListener('change',refreshPreview));
  V('#lpm-all').onclick=()=>{for(const x of filtered())selected.set(String(x.regulatoryProfileId),new Set((x.presentations||[]).map((p:any)=>String(p.packageId))));renderCandidates();refreshPreview()};V('#lpm-clear').onclick=()=>{selected.clear();renderCandidates();refreshPreview()};
  V('#lpm-save').onclick=async()=>{if(!selected.size)return notify('ກະລຸນາເລືອກຢ່າງໜ້ອຍ 1 ທະບຽນ',true);try{const payload={memo:memoFromForm(),items:selectionItems()};const r=await lpApi(memoId?'/registration-memos/'+encodeURIComponent(memoId):'/registration-memos',{method:memoId?'PATCH':'POST',body:JSON.stringify(payload)});memoId=r.data.memo.id;memo=r.data.memo;notify('ບັນທຶກໃບກິດສຳພັນສຳເລັດ')}catch(e:any){notify(e.message,true)}};
  V('#lpm-print').onclick=()=>printHtml(memoHtml());V('#lpm-word').onclick=()=>dl(`LVSP_Registration_Memo_${nameDate()}.doc`,`<html><head><meta charset="utf-8"><style>body{font-family:'Phetsarath OT','Noto Sans Lao',sans-serif}.lp-paper{width:180mm;margin:auto}table{border-collapse:collapse;width:100%}th,td{border:1px solid #222;padding:5px}</style></head><body>${memoHtml()}</body></html>`,'application/msword');
  renderCandidates();refreshPreview();
 }catch(e:any){body.innerHTML=`<div class="lp-empty">${E(e.message)}</div>`}}

function buildMemoPaper(m:any,rows:any[]){const purposes=(m.purposes||[]).map((x:string)=>PURPOSES[x]||x).join(', ')||'—';const grouped=new Map<string,any[]>();for(const r of rows){const k=m.groupByCompany?(r.registrationHolder||r.importer||'ບໍ່ລະບຸບໍລິສັດ'):'ALL';if(!grouped.has(k))grouped.set(k,[]);grouped.get(k)!.push(r)}const compCount=new Set(rows.map(r=>r.registrationHolder||r.importer).filter(Boolean)).size;const lead=m.leadText||`ພະແນກສັດຕະວະແພດ ຂໍລາຍງານ ແລະ ສະເໜີລາຍການຢາສັດຕະວະແພດຈຳນວນ ${rows.length} ລາຍການ${compCount?` ຈາກ ${compCount} ບໍລິສັດ`:''} ເພື່ອໃຫ້ຫົວໜ້າກົມພິຈາລະນາ/ຮັບຮູ້ການອອກທະບຽນ.`;let n=0;const sections=[...grouped.entries()].map(([company,rs])=>`${m.groupByCompany?`<div class="memo-company">${E(company)}</div>`:''}<table><thead><tr><th style="width:7%">ລ/ດ</th><th>ຊື່ຢາ / INN</th><th style="width:33%">ເລກທະບຽນ / ຂະໜາດ</th>${m.showCategory?'<th style="width:18%">ປະເພດ</th>':''}</tr></thead><tbody>${rs.map(r=>{n++;const ps=r.selectedPresentations||[];const reg=ps.length?ps.map((p:any,i:number)=>`<div><b>${E((r.registrationNo||'')+(m.showSubRegistration&&((r.presentations||[]).length>1)?'-'+(p.subCode||String(i+1).padStart(2,'0')):''))}</b>${m.showPack?`<span class="small"> · ${E([p.strengthText,p.packDescription].filter(Boolean).join(' · '))}</span>`:''}</div>`).join(''):`<b>${E(r.registrationNo||'')}</b>`;return `<tr><td style="text-align:center">${n}</td><td><b>${E(r.tradeName||'')}</b><div class="small">${E(r.genericName||r.activeIngredients||'')}</div></td><td>${reg}</td>${m.showCategory?`<td>${E(r.category||'')}<div class="small">${E(r.dosageForm||'')}</div></td>`:''}</tr>`}).join('')}</tbody></table>`).join('');const staff=(m.staffLines||[]).map((x:string,i:number)=>`<div>${i+1}. ${E(x)}</div>`).join('');return `<section class="lp-paper"><div class="country">ສາທາລະນະລັດ ປະຊາທິປະໄຕ ປະຊາຊົນລາວ</div><div class="motto">ສັນຕິພາບ ເອກະລາດ ປະຊາທິປະໄຕ ເອກະພາບ ວັດທະນາຖາວອນ</div><div class="memo-head"><div><b>${E(m.organizationName||'ກົມລ້ຽງສັດ ແລະ ການປະມົງ')}</b><br>${E(m.departmentName||'ພະແນກສັດຕະວະແພດ')}</div><div>ເລກທີ: <b>${E(m.memoNo||'........')}</b>/${E(m.memoSuffix||'')}<br>${E(m.placeText||'ນະຄອນຫຼວງ')}, ວັນທີ ${D(m.memoDate)}</div></div><h1>ໃບກິດສຳພັນພາຍໃນ</h1><p><b>ຮຽນ:</b> ${E(m.recipient||'')}</p><p><b>ເລື່ອງ:</b> ${E(m.subjectText||'')}</p><p class="purpose"><b>ຈຸດປະສົງ:</b> ${E(purposes)}</p><p>${E(lead)}</p>${sections||'<div class="lp-empty">ຍັງບໍ່ເລືອກທະບຽນ</div>'}${staff?`<div style="margin-top:12px"><b>ຄະນະ/ພະນັກງານ:</b>${staff}</div>`:''}<div class="sign-grid"><div><b>ພະນັກງານວິຊາການ</b><br><br><br>${E(m.signatoryNames?.technicalOfficer||'')}</div><div><b>ຫົວໜ້າພະແນກສັດຕະວະແພດ</b><br><br><br>${E(m.signatoryNames?.veterinaryHead||'')}</div><div><b>ຫົວໜ້າຂະແໜງ/ສັງລວມ</b><br><br><br>${E(m.signatoryNames?.sectionHead||'')}</div></div></section>`}

export async function openTradeCoordinationSheet(applicationId:string){ensureStyles();const d=makeDialog('lp-coord-dialog','📋 ໃບກິດສຳພັນ / ກວດເອກະສານນຳເຂົ້າ-ສົ່ງອອກ-ຜ່ານ');const body=d.querySelector('.lp-dialog-body') as HTMLElement;body.innerHTML='<div class="lp-empty">Loading…</div>';try{let r=await lpApi('/trade-coordination/'+encodeURIComponent(applicationId));let data=r.data,app=data.application,sheet=data.sheet||{sheetDate:isoToday(),status:'DRAFT',signatoryNames:{}};let items=data.items||[];body.innerHTML=`<div class="lp-coord-grid"><div class="lp-card"><div class="lp-form-grid"><label class="lp-field"><span>ຄຳຮ້ອງ / Application</span><input disabled value="${E(app.applicationNo||'')}"></label><label class="lp-field"><span>Permit No.</span><input disabled value="${E(app.permitNo||'')}"></label><label class="lp-field"><span>ບໍລິສັດ</span><input disabled value="${E(app.operatorName||'')}"></label><label class="lp-field"><span>ປະເພດ</span><input disabled value="${E(app.importType||'')}"></label><label class="lp-field"><span>ເລກທີໃບກິດສຳພັນ</span><input id="lpc-no" value="${E(sheet.sheetNo||'')}"></label><label class="lp-field"><span>ວັນທີ</span><input id="lpc-date" type="date" value="${E(String(sheet.sheetDate||isoToday()).slice(0,10))}"></label><label class="lp-field span2"><span>ເລື່ອງ</span><input id="lpc-subject" value="${E(sheet.subjectText||`ການພິຈາລະນາຄຳຮ້ອງ ${app.applicationNo||''}`)}"></label></div></div><div class="lp-card"><h3>ກວດຄວາມຄົບຖ້ວນ ແລະ ຄຸນນະພາບເອກະສານ</h3><div class="lp-table-wrap"><table class="lp-table lp-coord-table"><thead><tr><th>#</th><th>ເອກະສານ</th><th>ມີ/ບໍ່ມີ</th><th>ຖືກຕ້ອງ/ບໍ່ຖືກ</th><th>ເລກອ້າງອີງ</th><th>ໝາຍເຫດ</th></tr></thead><tbody>${items.map((x:any,i:number)=>`<tr data-code="${E(x.requirementCode)}"><td>${E(x.sequenceNo||i+1)}</td><td>${E(x.labelLo||x.labelSnapshot||'')}</td><td><select class="lpc-presence"><option value="PENDING" ${x.presenceStatus==='PENDING'?'selected':''}>—</option><option value="PRESENT" ${x.presenceStatus==='PRESENT'?'selected':''}>ມີ</option><option value="MISSING" ${x.presenceStatus==='MISSING'?'selected':''}>ບໍ່ມີ</option><option value="NOT_APPLICABLE" ${x.presenceStatus==='NOT_APPLICABLE'?'selected':''}>ບໍ່ນຳໃຊ້</option></select></td><td><select class="lpc-quality"><option value="PENDING" ${x.qualityStatus==='PENDING'?'selected':''}>—</option><option value="CORRECT" ${x.qualityStatus==='CORRECT'?'selected':''}>ຖືກຕ້ອງ</option><option value="INCORRECT" ${x.qualityStatus==='INCORRECT'?'selected':''}>ບໍ່ຖືກຕ້ອງ</option><option value="POLICY" ${x.qualityStatus==='POLICY'?'selected':''}>ນະໂຍບາຍ</option><option value="NOT_APPLICABLE" ${x.qualityStatus==='NOT_APPLICABLE'?'selected':''}>ບໍ່ນຳໃຊ້</option></select></td><td><input class="lpc-ref" value="${E(x.referenceNo||'')}"></td><td><input class="lpc-note" value="${E(x.notes||'')}"></td></tr>`).join('')}</tbody></table></div><div class="lp-form-grid" style="margin-top:10px"><label class="lp-field span2"><span>ຄຳເຫັນ/ສະຫຼຸບ</span><textarea id="lpc-comment" rows="3">${E(sheet.overallComment||'')}</textarea></label><label class="lp-field"><span>ຜູ້ກວດ</span><input id="lpc-reviewer" value="${E(sheet.reviewerName||'')}"></label><label class="lp-field"><span>ຕຳແໜ່ງ</span><input id="lpc-position" value="${E(sheet.reviewerPosition||'')}"></label><label class="lp-field"><span>ຫົວໜ້າຂະແໜງ/ພະແນກ</span><input id="lpc-head" value="${E(sheet.headSectionName||'')}"></label><label class="lp-field"><span>ສະຖານະ</span><select id="lpc-status">${['DRAFT','REVIEWED','READY','SIGNED','ARCHIVED','CANCELLED'].map(x=>`<option ${sheet.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="lp-field span2"><span>ຄຳເຫັນຮອງຫົວໜ້າ/ຜູ້ບໍລິຫານ</span><textarea id="lpc-deputy" rows="2">${E(sheet.deputyDirectorComment||'')}</textarea></label></div><div class="lp-actions" style="margin-top:10px"><button class="lp-btn primary" id="lpc-save">💾 ບັນທຶກ</button><button class="lp-btn gold" id="lpc-print">🖨 Print / PDF</button><button class="lp-btn" id="lpc-word">W Word</button></div></div><div class="lp-card"><h3>A4 Preview</h3><div id="lpc-preview"></div></div></div>`;
  function readItems(){return [...document.querySelectorAll('.lp-coord-table tbody tr')].map((tr:any)=>({requirementCode:tr.dataset.code,presenceStatus:tr.querySelector('.lpc-presence').value,qualityStatus:tr.querySelector('.lpc-quality').value,referenceNo:tr.querySelector('.lpc-ref').value,notes:tr.querySelector('.lpc-note').value}))}
  function readSheet(){return {sheetNo:V('#lpc-no').value,sheetDate:V('#lpc-date').value,subjectText:V('#lpc-subject').value,overallComment:V('#lpc-comment').value,reviewerName:V('#lpc-reviewer').value,reviewerPosition:V('#lpc-position').value,headSectionName:V('#lpc-head').value,deputyDirectorComment:V('#lpc-deputy').value,status:V('#lpc-status').value,signatoryNames:sheet.signatoryNames||{}}}
  function paper(){return buildCoordPaper(app,readSheet(),items,readItems())}function prev(){V('#lpc-preview').innerHTML=paper()}document.querySelectorAll('#lp-coord-dialog input,#lp-coord-dialog select,#lp-coord-dialog textarea').forEach(x=>x.addEventListener('input',prev));V('#lpc-save').onclick=async()=>{try{r=await lpApi('/trade-coordination/'+encodeURIComponent(applicationId),{method:'PUT',body:JSON.stringify({sheet:readSheet(),items:readItems()})});data=r.data;sheet=data.sheet;items=data.items;notify('ບັນທຶກການກວດເອກະສານສຳເລັດ')}catch(e:any){notify(e.message,true)}};V('#lpc-print').onclick=()=>printHtml(paper());V('#lpc-word').onclick=()=>dl(`LVSP_Trade_Coordination_${app.applicationNo||nameDate()}.doc`,`<html><head><meta charset="utf-8"><style>body{font-family:'Phetsarath OT','Noto Sans Lao'}table{border-collapse:collapse;width:100%}th,td{border:1px solid #222;padding:5px}</style></head><body>${paper()}</body></html>`,'application/msword');prev();
 }catch(e:any){body.innerHTML=`<div class="lp-empty">${E(e.message)}</div>`}}
function buildCoordPaper(app:any,s:any,baseItems:any[],live:any[]){const map=new Map(live.map(x=>[x.requirementCode,x]));const pLabel:any={PENDING:'—',PRESENT:'ມີ',MISSING:'ບໍ່ມີ',NOT_APPLICABLE:'ບໍ່ນຳໃຊ້'},qLabel:any={PENDING:'—',CORRECT:'ຖືກຕ້ອງ',INCORRECT:'ບໍ່ຖືກຕ້ອງ',POLICY:'ນະໂຍບາຍ',NOT_APPLICABLE:'ບໍ່ນຳໃຊ້'};return `<section class="lp-paper"><div class="country">ສາທາລະນະລັດ ປະຊາທິປະໄຕ ປະຊາຊົນລາວ</div><div class="motto">ສັນຕິພາບ ເອກະລາດ ປະຊາທິປະໄຕ ເອກະພາບ ວັດທະນາຖາວອນ</div><div class="memo-head"><div><b>ກົມລ້ຽງສັດ ແລະ ການປະມົງ</b><br>ພະແນກສັດຕະວະແພດ</div><div>ເລກທີ: ${E(s.sheetNo||'........')}<br>ວັນທີ ${D(s.sheetDate)}</div></div><h1>ໃບກິດສຳພັນ / ໃບກວດເອກະສານ</h1><p><b>ຄຳຮ້ອງ:</b> ${E(app.applicationNo||'')} &nbsp; <b>ບໍລິສັດ:</b> ${E(app.operatorName||'')}</p><p><b>ເລື່ອງ:</b> ${E(s.subjectText||'')}</p><table><thead><tr><th>#</th><th>ລາຍການເອກະສານ</th><th>ມີ/ບໍ່ມີ</th><th>ຄຸນນະພາບ</th><th>ອ້າງອີງ/ໝາຍເຫດ</th></tr></thead><tbody>${baseItems.map((b:any,i:number)=>{const x:any=map.get(b.requirementCode)||{};return `<tr><td>${i+1}</td><td>${E(b.labelLo||b.labelSnapshot||'')}</td><td>${E(pLabel[x.presenceStatus]||'—')}</td><td>${E(qLabel[x.qualityStatus]||'—')}</td><td>${E([x.referenceNo,x.notes].filter(Boolean).join(' · '))}</td></tr>`}).join('')}</tbody></table><p><b>ຄຳເຫັນ:</b> ${E(s.overallComment||'')}</p><div class="sign-grid"><div><b>ຜູ້ກວດ</b><br><br><br>${E(s.reviewerName||'')}<br><span class="small">${E(s.reviewerPosition||'')}</span></div><div><b>ຫົວໜ້າຂະແໜງ/ພະແນກ</b><br><br><br>${E(s.headSectionName||'')}</div><div><b>ຄຳເຫັນຜູ້ບໍລິຫານ</b><br><span class="small">${E(s.deputyDirectorComment||'')}</span></div></div></section>`}

const DRUG_COLS:any={registrationNo:'Registration No.',dlfNo:'DLF No.',dlfDate:'DLF/Registration Date',tradeName:'Trade Name',genericName:'Generic / INN',activeIngredients:'Active Ingredients',category:'Category',dosageForm:'Dosage Form',registrationType:'Registration Type',registrationHolder:'Registration Holder',importer:'Importer',manufacturerName:'Manufacturer',manufacturerCountry:'Manufacturing Country',validYears:'Valid Years',expiryDate:'Expiry Date',registrationStatus:'Status',presentationCount:'Presentations'};
const TRADE_COLS:any={permitNo:'Permit No.',applicationNo:'Application No.',movementType:'Type',applicationDate:'Application Date',decisionDate:'Decision Date',clearedDate:'Cleared Date',operatorName:'Operator',originCountry:'Origin',destinationCountry:'Destination',borderCheckpoint:'Checkpoint',itemCount:'Item Count',totalPacks:'Total Packs',totalValue:'Value',amrKg:'AMR kg',status:'Status'};
function defaults(source:string){return source==='drug'?['registrationNo','dlfDate','tradeName','genericName','category','dosageForm','registrationHolder','manufacturerName','expiryDate','registrationStatus']:['permitNo','movementType','applicationDate','decisionDate','operatorName','originCountry','destinationCountry','borderCheckpoint','itemCount','totalPacks','amrKg','status']}
function period(which:string){const n=new Date(),y=n.getFullYear(),m=n.getMonth();let a:any=null,b:any=null;if(which==='month'){a=new Date(y,m,1);b=new Date(y,m+1,0)}else if(which==='last'){a=new Date(y,m-1,1);b=new Date(y,m,0)}else if(which==='quarter'){const q=Math.floor(m/3)*3;a=new Date(y,q,1);b=new Date(y,q+3,0)}else if(which==='year'){a=new Date(y,0,1);b=new Date(y,11,31)}const f=(x:any)=>x?`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`:'';return [f(a),f(b)]}


