const MODULE_KEY_TO_REPORT_SOURCE:any={
 drug_registrations:'drug',trade_workspace:'trade',import_plans:'import_analytics',import_applications:'import_analytics',
 companies:'companies',products:'products',veterinary_devices:'devices',inspections:'inspections',
 laboratory_samples:'laboratory',disease_cases:'disease',trade_shipments:'shipments',gis_layers:'gis',animuse:'import_analytics'
};

export function moduleReportAvailable(moduleKey:string){return !!MODULE_KEY_TO_REPORT_SOURCE[moduleKey]}
export function openModuleReportForKey(moduleKey:string){const source=MODULE_KEY_TO_REPORT_SOURCE[moduleKey];if(!source)return notify('Report for this module will be enabled when the module is operational.',true);if(source==='import_analytics')return openImportPlanAnalyticsDashboard();if(source==='drug'||source==='trade')return openRegulatoryReportBuilder(source,'all');return openGenericModuleReport(source)}

function genericPresets(source:string){const cfg=GENERIC_REPORT_SOURCES[source];if(!cfg)return[];const rows:any[]=[{id:'all',label:'ລາຍການທັງໝົດ / All records',desc:'ລາຍງານຂໍ້ມູນຂອງ Module ນີ້ທັງໝົດ.',period:'all'}];if(cfg.dateField)rows.push({id:'year',label:'ປີນີ້ / This year',desc:`Filter by ${cfg.dateLabel||cfg.dateField}.`,period:'year'});if(cfg.statusField)rows.push({id:'status',label:'ຕາມສະຖານະ / By status',desc:'ໃສ່ Status filter ເພື່ອກັ່ນຕອງ.'});return rows}

export async function openGenericModuleReport(source:string){ensureStyles();const cfg=GENERIC_REPORT_SOURCES[source];if(!cfg)return notify('Report source is not available yet.',true);const d=makeDialog('lp-generic-report-dialog',`📊 ${cfg.label}`);const body=d.querySelector('.lp-dialog-body') as HTMLElement;let raw:any[]=[],data:any[]=[];
 body.innerHTML=`<div class="lp-card"><div class="lp-generic-filter-grid"><label class="lp-field"><span>Work Area</span><input value="${E(cfg.labelLo||cfg.label)}" disabled></label><label class="lp-field"><span>Report Type</span><select id="lpgr-preset"></select></label>${cfg.dateField?`<label class="lp-field"><span>${E(cfg.dateLabel||'Date')}</span><select id="lpgr-basis"><option value="${E(cfg.dateField)}">${E(cfg.dateLabel||cfg.dateField)}</option></select></label><label class="lp-field"><span>From</span><input id="lpgr-from" type="date"></label><label class="lp-field"><span>To</span><input id="lpgr-to" type="date"></label>`:'<div></div><div></div><div></div>'}<label class="lp-field wide"><span>Search</span><input id="lpgr-q" placeholder="Search any visible field..."></label>${cfg.statusField?'<label class="lp-field"><span>Status</span><input id="lpgr-status"></label>':'<div></div>'}<label class="lp-field"><span>Orientation</span><select id="lpgr-orientation"><option value="portrait">Portrait</option><option value="landscape">Landscape</option></select></label><div class="lp-field"><span>&nbsp;</span><button class="lp-btn primary" id="lpgr-run">🔎 Run Report</button></div></div><div id="lpgr-desc" class="lp-sub" style="margin:8px 0"></div><div class="lp-quick"><button class="lp-btn" data-gp="year">This Year</button><button class="lp-btn" data-gp="all">All</button></div><div><b style="font-size:12px">Columns</b><div id="lpgr-cols" class="lp-column-pick"></div></div><div class="lp-actions"><button class="lp-btn gold" id="lpgr-print">🖨 Print / PDF</button><button class="lp-btn" id="lpgr-xls">X Excel</button><button class="lp-btn" id="lpgr-csv">CSV</button></div></div><div class="lp-report-meta"><span id="lpgr-meta">0 records</span><span>${E(cfg.label)}</span></div><div id="lpgr-preview" class="lp-table-wrap"><div class="lp-empty">Run report…</div></div>`;
 const presets=genericPresets(source),ps=V('#lpgr-preset') as HTMLSelectElement;ps.innerHTML=presets.map((p:any)=>`<option value="${E(p.id)}">${E(p.label)}</option>`).join('');
 const cols=cfg.cols||{};V('#lpgr-cols').innerHTML=Object.entries(cols).map(([k,v])=>`<label><input class="lpgr-col" type="checkbox" value="${E(k)}" ${cfg.defaults.includes(k)?'checked':''}> ${E(v)}</label>`).join('');
 function chosen(){const c=[...document.querySelectorAll('.lpgr-col:checked')].map((x:any)=>x.value);return c.length?c:cfg.defaults}
 function applyPreset(){const p=presets.find((x:any)=>x.id===ps.value)||presets[0];V('#lpgr-desc').textContent=p?.desc||'';if(cfg.dateField&&p?.period==='year'){const [a,z]=period('year');V('#lpgr-from').value=a;V('#lpgr-to').value=z}else if(cfg.dateField&&p?.period==='all'){V('#lpgr-from').value='';V('#lpgr-to').value=''}}
 function filterRows(){const q=String(V('#lpgr-q')?.value||'').trim().toLowerCase(),status=cfg.statusField?String(V('#lpgr-status')?.value||'').trim().toLowerCase():'',from=cfg.dateField?String(V('#lpgr-from')?.value||''):'',to=cfg.dateField?String(V('#lpgr-to')?.value||''):'';return raw.filter((r:any)=>{if(q&&!Object.keys(cols).some(k=>String(r?.[k]??'').toLowerCase().includes(q)))return false;if(status&&!String(r?.[cfg.statusField]??'').toLowerCase().includes(status))return false;if(cfg.dateField&&(from||to)){const dt=String(r?.[cfg.dateField]||'').slice(0,10);if(from&&(!dt||dt<from))return false;if(to&&(!dt||dt>to))return false}return true})}
 function tableHtml(rows:any[],selected=chosen()){return `<table class="lp-table"><thead><tr>${selected.map((k:string)=>`<th>${E(cols[k]||k)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map((r:any)=>`<tr>${selected.map((k:string)=>`<td>${String(k).toLowerCase().includes('date')||String(k).toLowerCase().includes('at')?D(r[k]):E(r[k]??'')}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${selected.length}" class="lp-empty">No records</td></tr>`}</tbody></table>`}
 function paper(){const ori=V('#lpgr-orientation').value,selected=chosen();return `<section class="lp-paper lp-report-paper ${ori==='landscape'?'report-landscape':''}"><div class="country">ສາທາລະນະລັດ ປະຊາທິປະໄຕ ປະຊາຊົນລາວ</div><div class="motto">ສັນຕິພາບ ເອກະລາດ ປະຊາທິປະໄຕ ເອກະພາບ ວັດທະນາຖາວອນ</div><div style="text-align:center;margin-top:8px"><b>ກະຊວງກະສິກຳ ແລະ ສິ່ງແວດລ້ອມ</b><br>ກົມລ້ຽງສັດ ແລະ ການປະມົງ</div><h1>${E(cfg.titleLo||cfg.label)}</h1><div class="rmeta">Report Type: ${E(ps.options[ps.selectedIndex]?.text||'All')} · Records: ${data.length} · ${D(isoToday())}</div>${tableHtml(data,selected)}<div class="lp-signline"><div><b>ຜູ້ຢັ້ງຢືນ/ຜູ້ອະນຸມັດ</b><br><br><br>.....................................</div></div></section>`}
 async function run(){try{V('#lpgr-preview').innerHTML='<div class="lp-empty">Loading…</div>';const r=await coreApi(cfg.endpoint);raw=Array.isArray(r.data)?r.data:[];data=filterRows();V('#lpgr-preview').innerHTML=tableHtml(data);V('#lpgr-meta').textContent=`${data.length} records`;}catch(e:any){V('#lpgr-preview').innerHTML=`<div class="lp-empty">${E(e.message)}</div>`;notify(e.message,true)}}
 ps.onchange=()=>{applyPreset();if(raw.length){data=filterRows();V('#lpgr-preview').innerHTML=tableHtml(data);V('#lpgr-meta').textContent=`${data.length} records`}};applyPreset();V('#lpgr-run').onclick=run;document.querySelectorAll('[data-gp]').forEach(b=>b.addEventListener('click',()=>{const x=(b as HTMLElement).dataset.gp;if(cfg.dateField){if(x==='year'){const[a,z]=period('year');V('#lpgr-from').value=a;V('#lpgr-to').value=z}else{V('#lpgr-from').value='';V('#lpgr-to').value=''}}run()}));
 V('#lpgr-print').onclick=()=>{if(!data.length)return notify('Run report first',true);printHtml(paper())};V('#lpgr-xls').onclick=()=>{if(!data.length)return notify('Run report first',true);dl(`LVSP_${source}_report_${nameDate()}.xls`,`<html><head><meta charset="utf-8"></head><body>${tableHtml(data)}</body></html>`,'application/vnd.ms-excel')};V('#lpgr-csv').onclick=()=>{if(!data.length)return notify('Run report first',true);const selected=chosen(),cell=(v:any)=>'"'+String(v??'').replaceAll('"','""')+'"';dl(`LVSP_${source}_report_${nameDate()}.csv`,[selected.map((k:string)=>cell(cols[k]||k)).join(','),...data.map((r:any)=>selected.map((k:string)=>cell(r[k])).join(','))].join('\r\n'),'text/csv;charset=utf-8')};await run();
}

