export async function renderRegulatoryReportsPage(){ensureStyles();const root=V('#custom-page');if(!root)return;V('#page-title').textContent='ສູນລາຍງານ / Central Report Center';V('#page-subtitle').textContent='Hybrid Reporting — Module detail reports + cross-module management overview';
 let meta:any={counts:{}},analytics:any={summary:{}},publicCatalog:any[]=[];try{const [m,a,c]=await Promise.all([coreApi('/meta'),lpApi(`/reports/import-analytics?year=${new Date().getFullYear()}`),coreApi('/public/module-catalog')]);meta=m.data||{counts:{}};analytics=a.data||{summary:{}};publicCatalog=c.data||[]}catch{}
 const counts=meta.counts||{},sum=analytics.summary||{},statusMap=new Map((publicCatalog||[]).map((x:any)=>[String(x.moduleCode),String(x.deliveryStatus||'')]));
 const ready=MODULE_REPORT_CATALOG.filter(x=>x.source&&x.source!=='all').length,planned=MODULE_REPORT_CATALOG.filter(x=>!x.source).length;
 const statusLabel=(x:any)=>x.status==='PLANNED'?'Planned':x.status==='EXECUTIVE'?'Executive':'Report Ready';
 const statusClass=(x:any)=>x.status==='PLANNED'?'planned':x.status==='EXECUTIVE'?'analytics':'ready';
 const cards=MODULE_REPORT_CATALOG.filter(x=>x.moduleCode!=='CENTRAL_REPORTS').map((x:any)=>{const platform=statusMap.get(x.moduleCode),plannedState=x.status==='PLANNED',detail=platform?`Platform: ${platform.replaceAll('_',' ')}`:statusLabel(x);return `<article class="lp-report-source-card ${plannedState?'is-planned':''}"><div class="lp-report-source-top"><span class="lp-report-source-icon">${E(x.icon)}</span><span class="lp-report-status ${statusClass(x)}">${E(detail)}</span></div><h4>${E(x.nameLo)}<span class="lp-sub">${E(x.nameEn)}</span></h4><p>${E(x.descLo||'')}</p><button class="lp-btn ${x.source?'':'disabled'}" data-report-source="${E(x.source||'')}" ${x.source?'':'disabled'}>${x.source?(x.source==='trade'?'📄 Report':'📊 Open Report'):'ລໍຖ້າ Module ພ້ອມ'}</button></article>`}).join('');
 root.innerHTML=`<div class="lp-center"><div class="lp-hero"><div><span class="lp-kicker">HYBRID REPORTING ARCHITECTURE</span><h2>ສູນລາຍງານກາງ + ລາຍງານປະຈຳ Module</h2><p>Central Report Center ໃຊ້ສຳລັບພາບລວມ, KPI ແລະການປຽບທຽບຂ້າມໜ້າວຽກ. ສ່ວນລາຍງານລະອຽດແມ່ນຢູ່ໃນ Module ຂອງໃຜລາວ ແລະເຂົ້າໄດ້ຈາກສູນນີ້ອີກທາງ.</p></div></div>
 <div class="lp-report-architecture"><div class="lp-arch-card"><b>1. Module Report = ລາຍລະອຽດວຽກ</b><p>ແຕ່ລະ Module ມີ Filter, columns, PDF/Excel/CSV ຕາມລັກສະນະວຽກຂອງຕົນ.</p></div><div class="lp-arch-card"><b>2. Central = ພາບລວມບໍລິຫານ</b><p>ສັງລວມ KPI ແລະເປັນຈຸດເຂົ້າຫາລາຍງານຂອງທຸກ Module.</p></div><div class="lp-arch-card"><b>3. No fake reports</b><p>Module ທີ່ຍັງ Planned ຈະສະແດງໄວ້ແຕ່ບໍ່ສ້າງຕົວເລກປອມ; Report ຈະເປີດເມື່ອ operational data ພ້ອມ.</p></div></div>
 <section class="lp-card"><h3>📊 All LVSP Executive Overview — ${new Date().getFullYear()}</h3><div class="lp-exec-kpis"><div class="lp-exec-kpi"><b>${E(counts.drug_registrations||0)}</b><span>Drug Registrations</span></div><div class="lp-exec-kpi"><b>${E(counts.import_applications||0)}</b><span>Trade Applications</span></div><div class="lp-exec-kpi"><b>${E(counts.import_plans||0)}</b><span>Annual Plans</span></div><div class="lp-exec-kpi"><b>${E(counts.companies||0)}</b><span>Companies</span></div><div class="lp-exec-kpi"><b>${E(sum.importCount||0)}</b><span>Actual Imports / Clearance</span></div><div class="lp-exec-kpi"><b>$${Number(sum.actualClearedValueUsd||0).toLocaleString(undefined,{maximumFractionDigits:0})}</b><span>Actual Trade Value</span></div></div><div class="lp-report-control-note">Report-ready sources: ${ready} · Planned sources: ${planned}. ຕົວເລກຈະຂະຫຍາຍອັດຕະໂນມັດຕາມ Module ທີ່ມີຂໍ້ມູນຈິງ.</div></section>
 <div class="lp-analytics-grid"><section class="lp-card"><h3>📄 Report by Work Area</h3><div class="lp-report-controls" style="grid-template-columns:1fr 1.5fr auto"><label class="lp-field"><span>1. ໜ້າວຽກ / Work Area</span><select id="lpr-page-source"><option value="all">All LVSP / Executive Overview</option>${MODULE_REPORT_CATALOG.filter(x=>x.moduleCode!=='CENTRAL_REPORTS').map((x:any)=>`<option value="${E(x.source||'planned:'+x.moduleCode)}">${E(x.nameEn)}${x.source?'':' — PLANNED'}</option>`).join('')}</select></label><label class="lp-field"><span>2. ປະເພດລາຍງານ / Report Type</span><select id="lpr-page-preset"></select></label><div class="lp-field"><span>&nbsp;</span><button class="lp-btn primary" id="lpr-page-open">ເປີດ Report →</button></div></div><div id="lpr-page-desc" class="lp-sub" style="margin-top:10px"></div></section><section class="lp-card"><h3>📈 Import Plan & Analytics</h3><p style="font-size:13px;color:#5d7069">Plan → Approved → Actual/Cleared → Remaining, Top Companies, Top Products, Checkpoints, Origin Countries ແລະ transaction drill-down.</p><div class="lp-actions"><button class="lp-btn gold" id="lpr-open-analytics">📈 ເປີດ Import Analytics</button></div><div class="lp-analytics-note">Quantity ບໍ່ຖືກບວກ/ຫັກຂ້າມຫົວໜ່ວຍ; Summary plan ແບບ “ລາຍການ” ຕິດຕາມ Item Count/Value.</div></section></div>
 <section class="lp-card" style="margin-top:12px"><h3>🧭 Report Coverage by Module</h3><div class="lp-report-catalog">${cards}</div></section></div>`;
 const presetList=(source:string)=>{if(source==='all')return[{id:'executive',label:'Executive Overview',desc:'ພາບລວມ KPI ຂ້າມ Module.'}];if(source.startsWith('planned:'))return[{id:'planned',label:'Planned — Report not active yet',desc:'Module ນີ້ຍັງບໍ່ມີ operational dataset ສຳລັບ report.'}];if(source==='drug'||source==='trade')return reportPresetList(source);return genericPresets(source)};
 const fill=()=>{const source=V('#lpr-page-source').value,list=presetList(source),sel=V('#lpr-page-preset') as HTMLSelectElement;sel.innerHTML=list.map((p:any)=>`<option value="${E(p.id)}">${E(p.label)}</option>`).join('');V('#lpr-page-desc').textContent=list[0]?.desc||'';(V('#lpr-page-open') as HTMLButtonElement).disabled=source.startsWith('planned:')};fill();
 V('#lpr-page-source').onchange=fill;V('#lpr-page-preset').onchange=()=>{const p=presetList(V('#lpr-page-source').value).find((x:any)=>x.id===V('#lpr-page-preset').value);V('#lpr-page-desc').textContent=p?.desc||''};
 V('#lpr-page-open').onclick=()=>{const source=V('#lpr-page-source').value;if(source==='all')return V('.lp-exec-kpis')?.scrollIntoView({behavior:'smooth',block:'center'});if(source.startsWith('planned:'))return notify('Module report will open when operational data is ready.',true);if(source==='drug'||source==='trade')return openRegulatoryReportBuilder(source,V('#lpr-page-preset').value);return openGenericModuleReport(source)};
 V('#lpr-open-analytics').onclick=()=>openImportPlanAnalyticsDashboard();document.querySelectorAll('[data-report-source]').forEach(b=>b.addEventListener('click',()=>{const source=(b as HTMLElement).dataset.reportSource||'';if(!source)return;if(source==='drug'||source==='trade')openRegulatoryReportBuilder(source,'all');else openGenericModuleReport(source)}))
}


export async function openImportPlanAnalyticsDashboard(){ensureStyles();const d=makeDialog('lp-import-analytics','📊 Import Plan & Analytics');const body=d.querySelector('.lp-dialog-body') as HTMLElement;let currentData:any=null;const n=(v:any,d=0)=>Number(v||0).toLocaleString(undefined,{maximumFractionDigits:d});const money=(v:any)=>'$'+Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});const statusClass=(v:any)=>String(v)==='OVER_PLAN'?'lp-track-over':String(v)==='UNIT_MISMATCH'?'lp-track-warn':'lp-track-ok';
 body.innerHTML=`<div class="lp-card"><div class="lp-analytics-filters"><label class="lp-field"><span>Year / ປີ</span><input id="lpa-year" type="number" value="${new Date().getFullYear()}"></label><label class="lp-field"><span>From / ແຕ່ວັນທີ</span><input id="lpa-from" type="date"></label><label class="lp-field"><span>To / ຫາວັນທີ</span><input id="lpa-to" type="date"></label><label class="lp-field"><span>Company / ບໍລິສັດ</span><input id="lpa-company" placeholder="ຊື່ບໍລິສັດ"></label><label class="lp-field"><span>Product / Drug / Permit</span><input id="lpa-q" placeholder="ຊື່ຢາ, Reg No., Permit..."></label><label class="lp-field"><span>Category / ໝວດ</span><input id="lpa-category" placeholder="Medicine / Vaccine / Device..."></label><label class="lp-field"><span>Origin Country</span><input id="lpa-origin"></label><label class="lp-field"><span>Checkpoint / ດ່ານ</span><input id="lpa-checkpoint"></label><label class="lp-field"><span>Movement</span><select id="lpa-movement"><option value="">All</option><option selected>IMPORT</option><option>EXPORT</option><option>TRANSIT</option></select></label><label class="lp-field"><span>Status</span><select id="lpa-status"><option value="">All</option><option>APPROVED</option><option>CLEARED</option><option>CLOSED</option><option>COMPLETED</option><option>UNDER_REVIEW</option></select></label></div><div class="lp-analytics-actions" style="margin-top:9px"><button class="lp-btn primary" id="lpa-run">🔎 Run Analytics</button><button class="lp-btn" id="lpa-clear">Clear Filters</button><button class="lp-btn" id="lpa-xls">X Excel Analytics</button><button class="lp-btn" id="lpa-csv">CSV Transactions</button></div><div class="lp-analytics-note"><b>Safe tracking rule:</b> LVSP ບໍ່ລວມ “ຂວດ + ກ່ອງ + ອັນ” ເປັນ quantity ດຽວ. Product ranking ຈະແຍກຕາມ Unit; Summary/Category plan ເຊັ່ນ “20 ລາຍການ” ຈະຕິດຕາມ Item Count (ແລະ Value ຖ້າມີ) ໂດຍບໍ່ຫັກກັບຈຳນວນຂວດ/ກ່ອງ.</div></div><div id="lpa-kpis" class="lp-analytics-kpis"></div><div class="lp-analytics-grid"><div class="lp-analytics-card lp-analytics-wide"><h3>Plan vs Actual</h3><div id="lpa-plan" class="lp-table-wrap"><div class="lp-empty">Run analytics…</div></div></div><div class="lp-analytics-card"><h3>Top Companies</h3><div id="lpa-companies" class="lp-table-wrap"></div></div><div class="lp-analytics-card"><h3>Top Products / Drugs</h3><div id="lpa-products" class="lp-table-wrap"></div></div><div class="lp-analytics-card"><h3>Checkpoints</h3><div id="lpa-checkpoints" class="lp-table-wrap"></div></div><div class="lp-analytics-card"><h3>Origin Countries</h3><div id="lpa-origins" class="lp-table-wrap"></div></div><div class="lp-analytics-card lp-analytics-wide"><h3>Transaction Drill-down</h3><div id="lpa-transactions" class="lp-table-wrap"></div></div></div>`;
 function query(){const p=new URLSearchParams();for(const [id,key] of [['#lpa-year','year'],['#lpa-from','from'],['#lpa-to','to'],['#lpa-company','company'],['#lpa-q','q'],['#lpa-category','category'],['#lpa-origin','originCountry'],['#lpa-checkpoint','checkpoint'],['#lpa-movement','movementType'],['#lpa-status','status']] as any[]){const v=String(V(id).value||'').trim();if(v)p.set(key,v)}return p}
 function table(rows:any[],cols:any[],empty='No records'){return `<table class="lp-table"><thead><tr>${cols.map(c=>`<th>${E(c[1])}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${cols.map(c=>`<td>${c[2]?c[2](r[c[0]],r):E(r[c[0]]??'—')}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${cols.length}" class="lp-empty">${E(empty)}</td></tr>`}</tbody></table>`}
 function draw(x:any){currentData=x;const s=x.summary||{};V('#lpa-kpis').innerHTML=[['Approvals',n(s.approvalCount)],['Actual Imports / Clearance',n(s.importCount)],['Companies',n(s.companyCount)],['Unique Products',n(s.uniqueItemCount)],['Actual Value',money(s.actualClearedValueUsd)],['Over Plan',n(s.overPlanCount)],['Unlinked Lines',n(s.unlinkedLineCount)]].map(k=>`<div class="lp-kpi"><b>${E(k[1])}</b><span>${E(k[0])}</span></div>`).join('');
  V('#lpa-plan').innerHTML=table(x.planTracking||[],[['companyName','Company'],['itemName','Plan item'],['trackingBasis','Tracking'],['plannedQuantity','Plan Qty',(v:any,r:any)=>r.trackingBasis==='QUANTITY'||r.trackingBasis==='QUANTITY_VALUE'?`${n(v,3)} ${E(r.unitCode||'')}`:'—'],['plannedItemCount','Plan Items',(v:any,r:any)=>r.trackingBasis==='COUNT_VALUE'?n(v):'—'],['plannedValueUsd','Plan Value',(v:any)=>v===null||v===undefined?'—':money(v)],['approvedQuantity','Approved Qty',(v:any,r:any)=>r.trackingBasis==='QUANTITY'||r.trackingBasis==='QUANTITY_VALUE'?`${n(v,3)} ${E(r.unitCode||'')}`:'—'],['approvedItemCount','Approved Items',(v:any,r:any)=>r.trackingBasis==='COUNT_VALUE'?n(v):'—'],['approvedValueUsd','Approved Value',(v:any)=>money(v)],['actualClearedQuantity','Actual Qty',(v:any,r:any)=>r.trackingBasis==='QUANTITY'||r.trackingBasis==='QUANTITY_VALUE'?`${n(v,3)} ${E(r.unitCode||'')}`:'—'],['actualItemCount','Actual Items',(v:any,r:any)=>r.trackingBasis==='COUNT_VALUE'?n(v):'—'],['actualClearedValueUsd','Actual Value',(v:any)=>money(v)],['approvalCount','Approvals',(v:any)=>n(v)],['importCount','Imports',(v:any)=>n(v)],['trackingStatus','Status',(v:any)=>`<span class="${statusClass(v)}">${E(v)}</span>`]],'No annual-plan rows for these filters');
  V('#lpa-companies').innerHTML=table(x.companies||[],[['companyName','Company'],['approvalCount','Approvals',(v:any)=>n(v)],['importCount','Actual Imports',(v:any)=>n(v)],['uniqueItemCount','Products',(v:any)=>n(v)],['approvedValueUsd','Approved USD',(v:any)=>money(v)],['actualClearedValueUsd','Actual USD',(v:any)=>money(v)]]);
  V('#lpa-products').innerHTML=table(x.products||[],[['itemName','Product / Drug'],['registrationNo','Reg No.'],['unitCode','Unit'],['approvedQuantity','Approved Qty',(v:any)=>n(v,3)],['actualClearedQuantity','Actual Qty',(v:any)=>n(v,3)],['approvalCount','Approvals',(v:any)=>n(v)],['importCount','Actual Imports',(v:any)=>n(v)],['companyCount','Companies',(v:any)=>n(v)],['approvedValueUsd','Approved USD',(v:any)=>money(v)],['actualClearedValueUsd','Actual USD',(v:any)=>money(v)]]);
  V('#lpa-checkpoints').innerHTML=table(x.checkpoints||[],[['borderCheckpoint','Checkpoint'],['importCount','Times',(v:any)=>n(v)],['companyCount','Companies',(v:any)=>n(v)],['actualClearedValueUsd','USD',(v:any)=>money(v)]]);
  V('#lpa-origins').innerHTML=table(x.origins||[],[['originCountry','Country'],['importCount','Times',(v:any)=>n(v)],['uniqueItemCount','Products',(v:any)=>n(v)],['actualClearedValueUsd','USD',(v:any)=>money(v)]]);
  V('#lpa-transactions').innerHTML=table(x.transactions||[],[['applicationDate','Date',(v:any)=>D(v)],['companyName','Company'],['permitNo','Permit'],['itemName','Item'],['registrationNo','Reg No.'],['clearedQuantity','Cleared',(v:any,r:any)=>`${n(v,3)} ${E(r.unitCode||'')}`],['actualClearedValueUsd','Actual USD',(v:any)=>money(v)],['borderCheckpoint','Checkpoint'],['applicationStatus','Status']]);
 }
 async function run(){try{V('#lpa-plan').innerHTML='<div class="lp-empty">Loading…</div>';const r=await lpApi('/reports/import-analytics?'+query().toString());draw(r.data||{})}catch(e:any){V('#lpa-plan').innerHTML=`<div class="lp-empty">${E(e.message)}</div>`;notify(e.message,true)}}
 V('#lpa-run').onclick=run;V('#lpa-clear').onclick=()=>{for(const id of ['#lpa-from','#lpa-to','#lpa-company','#lpa-q','#lpa-category','#lpa-origin','#lpa-checkpoint','#lpa-status'])V(id).value='';V('#lpa-movement').value='IMPORT';V('#lpa-year').value=String(new Date().getFullYear());run()};V('#lpa-xls').onclick=()=>{if(!currentData)return notify('Run analytics first',true);const x=currentData;const section=(title:string,rows:any[],cols:any[])=>`<h2>${E(title)}</h2>${table(rows||[],cols)}`;const html=`<html><head><meta charset="utf-8"><style>body{font-family:'Phetsarath OT','Noto Sans Lao',Arial}table{border-collapse:collapse;width:100%;font-size:9pt;margin-bottom:20px}th,td{border:1px solid #777;padding:4px;vertical-align:top}th{background:#eaf3ef}</style></head><body><h1>LVSP Import Plan & Analytics</h1><p>${E(query().toString())}</p>${section('Plan vs Actual',x.planTracking,[['companyName','Company'],['itemName','Plan item'],['trackingBasis','Tracking'],['plannedQuantity','Plan Qty'],['plannedItemCount','Plan Items'],['plannedValueUsd','Plan Value USD'],['approvedQuantity','Approved Qty'],['approvedItemCount','Approved Items'],['approvedValueUsd','Approved USD'],['actualClearedQuantity','Actual Qty'],['actualItemCount','Actual Items'],['actualClearedValueUsd','Actual USD'],['approvalCount','Approvals'],['importCount','Imports'],['trackingStatus','Status']])}${section('Top Companies',x.companies,[['companyName','Company'],['approvalCount','Approvals'],['importCount','Actual Imports'],['uniqueItemCount','Products'],['approvedValueUsd','Approved USD'],['actualClearedValueUsd','Actual USD']])}${section('Top Products / Drugs',x.products,[['itemName','Product / Drug'],['registrationNo','Reg No.'],['unitCode','Unit'],['approvedQuantity','Approved Qty'],['actualClearedQuantity','Actual Qty'],['approvalCount','Approvals'],['importCount','Actual Imports'],['companyCount','Companies'],['actualClearedValueUsd','Actual USD']])}${section('Checkpoints',x.checkpoints,[['borderCheckpoint','Checkpoint'],['importCount','Times'],['companyCount','Companies'],['actualClearedValueUsd','USD']])}${section('Origin Countries',x.origins,[['originCountry','Country'],['importCount','Times'],['uniqueItemCount','Products'],['actualClearedValueUsd','USD']])}</body></html>`;dl(`LVSP_import_analytics_${nameDate()}.xls`,html,'application/vnd.ms-excel')};V('#lpa-csv').onclick=()=>{if(!currentData)return notify('Run analytics first',true);const rows=currentData.transactions||[],cols=['applicationDate','companyName','applicationNo','permitNo','itemName','registrationNo','requestedQuantity','approvedQuantity','clearedQuantity','unitCode','actualClearedValueUsd','originCountry','borderCheckpoint','applicationStatus'];const cell=(v:any)=>'"'+String(v??'').replaceAll('"','""')+'"';dl(`LVSP_import_transactions_${nameDate()}.csv`,[cols.map(cell).join(','),...rows.map((r:any)=>cols.map(k=>cell(r[k])).join(','))].join('\r\n'),'text/csv;charset=utf-8')};await run();
}

export async function openRegulatoryReportBuilder(initialSource='drug',initialPreset='all'){ensureStyles();const d=makeDialog('lp-report-dialog','📊 Central Regulatory Report Builder');const body=d.querySelector('.lp-dialog-body') as HTMLElement;let source=initialSource==='trade'?'trade':'drug',data:any[]=[];body.innerHTML=`<div class="lp-card"><div class="lp-report-controls"><label class="lp-field"><span>Work Area / Data Source</span><select id="lpr-source"><option value="drug" ${source==='drug'?'selected':''}>Veterinary Drug Registration</option><option value="trade" ${source==='trade'?'selected':''}>Import / Export / Transit</option></select></label><label class="lp-field"><span>Report Type</span><select id="lpr-preset"></select></label><label class="lp-field"><span>Date Basis</span><select id="lpr-basis"></select></label><label class="lp-field"><span>From</span><input id="lpr-from" type="date"></label><label class="lp-field"><span>To</span><input id="lpr-to" type="date"></label><label class="lp-field wide"><span>Search</span><input id="lpr-q" placeholder="Reg No. / Permit / Product / Company"></label><label class="lp-field"><span>Status</span><input id="lpr-status"></label><label class="lp-field"><span>Category / Movement</span><input id="lpr-kind"></label><label class="lp-field"><span>Company</span><input id="lpr-company"></label><label class="lp-field"><span>Orientation</span><select id="lpr-orientation"><option value="portrait">Portrait</option><option value="landscape">Landscape</option></select></label><div class="lp-field"><span>&nbsp;</span><button class="lp-btn primary" id="lpr-load">🔎 Run Report</button></div></div><div id="lpr-preset-desc" class="lp-sub" style="margin:7px 0 10px"></div><div class="lp-quick"><button class="lp-btn" data-p="month">This Month</button><button class="lp-btn" data-p="last">Last Month</button><button class="lp-btn" data-p="quarter">This Quarter</button><button class="lp-btn" data-p="year">This Year</button><button class="lp-btn" data-p="all">All</button></div><div><b style="font-size:12px">Columns</b><div id="lpr-cols" class="lp-column-pick"></div></div><div class="lp-actions"><button class="lp-btn gold" id="lpr-print">🖨 Print / PDF</button><button class="lp-btn" id="lpr-word">W Word</button><button class="lp-btn" id="lpr-xls">X Excel</button><button class="lp-btn" id="lpr-csv">CSV</button></div></div><div class="lp-report-meta"><span id="lpr-meta">0 records</span><span id="lpr-filter-meta"></span></div><div id="lpr-preview" class="lp-table-wrap"><div class="lp-empty">Run report…</div></div>`;
 function populatePresetOptions(wanted='all'){const list=reportPresetList(source),sel=V('#lpr-preset') as HTMLSelectElement;sel.innerHTML=list.map((p:any)=>`<option value="${E(p.id)}">${E(p.label)}</option>`).join('');sel.value=list.some((p:any)=>p.id===wanted)?wanted:'all'}
 function configure(wantedPreset='all'){source=V('#lpr-source').value;V('#lpr-basis').innerHTML=(source==='drug'?[['DLF_DATE','DLF Date'],['REGISTRATION_DATE','Registration Date'],['EXPIRY_DATE','Expiry Date'],['APPLICATION_DATE','Application Date']]:[['APPLICATION_DATE','Application Date'],['DECISION_DATE','Decision Date'],['CLEARED_DATE','Cleared Date']]).map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('');const cols=source==='drug'?DRUG_COLS:TRADE_COLS,defs=defaults(source);V('#lpr-cols').innerHTML=Object.entries(cols).map(([k,v])=>`<label><input class="lpr-col" type="checkbox" value="${k}" ${defs.includes(k)?'checked':''}> ${E(v)}</label>`).join('');V('#lpr-kind').placeholder=source==='drug'?'Category':'IMPORT / EXPORT / TRANSIT';populatePresetOptions(wantedPreset);applyPreset()}
 function applyPreset(){const p=reportPresetList(source).find((x:any)=>x.id===V('#lpr-preset').value)||reportPresetList(source)[0];V('#lpr-preset-desc').textContent=p?.desc||'';V('#lpr-basis').value=p?.dateBasis||V('#lpr-basis').value;V('#lpr-status').value=p?.status||'';V('#lpr-kind').value=p?.movementType||p?.category||'';if(p?.period==='all'){V('#lpr-from').value='';V('#lpr-to').value=''}else if(p?.period){const [a,z]=period(p.period);V('#lpr-from').value=a;V('#lpr-to').value=z}}
 function chosen(){const all=source==='drug'?DRUG_COLS:TRADE_COLS;const c=[...document.querySelectorAll('.lpr-col:checked')].map((x:any)=>x.value);return c.length?c:Object.keys(all).slice(0,8)}
 function query(){const p=new URLSearchParams();for(const [id,key] of [['#lpr-from','from'],['#lpr-to','to'],['#lpr-q','q'],['#lpr-status','status'],['#lpr-company','company']] as any[]){const v=V(id).value.trim();if(v)p.set(key,v)}p.set('dateBasis',V('#lpr-basis').value);const kind=V('#lpr-kind').value.trim();if(kind)p.set(source==='drug'?'category':'movementType',kind);return p}
 function tableHtml(rows:any[],cols:string[],forPrint=false){const labels=source==='drug'?DRUG_COLS:TRADE_COLS;return `<table class="lp-table"><thead><tr>${cols.map(k=>`<th>${E(labels[k]||k)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${cols.map(k=>`<td>${k.toLowerCase().includes('date')?D(r[k]):E(r[k]??'')}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${cols.length}" class="lp-empty">No records</td></tr>`}</tbody></table>`}
 function officialPaper(){const cols=chosen(),q=query(),ori=V('#lpr-orientation').value,preset=reportPresetList(source).find((x:any)=>x.id===V('#lpr-preset').value);const title=source==='drug'?'ບົດລາຍງານທະບຽນຢາສັດຕະວະແພດ':'ບົດລາຍງານ Import / Export / Transit';const periodText=q.get('from')||q.get('to')?`${D(q.get('from'))} — ${D(q.get('to'))}`:'All records';const filters=[preset?.label,q.get('status')&&`Status=${q.get('status')}`,q.get('category')&&`Category=${q.get('category')}`,q.get('movementType')&&`Type=${q.get('movementType')}`,q.get('company')&&`Company=${q.get('company')}`].filter(Boolean).join(' · ')||'No additional filters';return `<section class="lp-paper lp-report-paper ${ori==='landscape'?'report-landscape':''}"><div class="country">ສາທາລະນະລັດ ປະຊາທິປະໄຕ ປະຊາຊົນລາວ</div><div class="motto">ສັນຕິພາບ ເອກະລາດ ປະຊາທິປະໄຕ ເອກະພາບ ວັດທະນາຖາວອນ</div><div style="text-align:center;margin-top:8px"><b>ກະຊວງກະສິກຳ ແລະ ສິ່ງແວດລ້ອມ</b><br>ກົມລ້ຽງສັດ ແລະ ການປະມົງ</div><h1>${title}</h1><div class="rmeta">ປະເພດ: ${E(preset?.label||'')}<br>ໄລຍະ: ${E(periodText)} · ${E(filters)}<br>ຈຳນວນ: ${data.length} ລາຍການ · ພິມວັນທີ ${D(isoToday())}</div>${tableHtml(data,cols,true)}<div class="lp-signline"><div><b>ຜູ້ຢັ້ງຢືນ/ຜູ້ອະນຸມັດ</b><br><br><br>.....................................</div></div></section>`}
 async function run(){try{V('#lpr-preview').innerHTML='<div class="lp-empty">Loading…</div>';const p=query();const r=await lpApi(`/reports/${source==='drug'?'drugs':'trade'}?${p.toString()}`);data=r.data||[];const cols=chosen();V('#lpr-preview').innerHTML=tableHtml(data,cols);V('#lpr-meta').textContent=`${data.length} records`;V('#lpr-filter-meta').textContent=`Date basis: ${r.meta?.dateBasis||''}`}catch(e:any){V('#lpr-preview').innerHTML=`<div class="lp-empty">${E(e.message)}</div>`;notify(e.message,true)}}
 V('#lpr-source').onchange=()=>{configure('all');data=[];V('#lpr-preview').innerHTML='<div class="lp-empty">Run report…</div>'};V('#lpr-preset').onchange=()=>{applyPreset();data=[];V('#lpr-preview').innerHTML='<div class="lp-empty">Run report…</div>'};V('#lpr-load').onclick=run;document.querySelectorAll('[data-p]').forEach(b=>b.addEventListener('click',()=>{const x=(b as HTMLElement).dataset.p;if(x==='all'){V('#lpr-from').value='';V('#lpr-to').value=''}else{const [a,z]=period(x||'');V('#lpr-from').value=a;V('#lpr-to').value=z}run()}));
 V('#lpr-print').onclick=()=>{if(!data.length)return notify('Run report first',true);printHtml(officialPaper())};V('#lpr-word').onclick=()=>{if(!data.length)return notify('Run report first',true);dl(`LVSP_${source}_report_${nameDate()}.doc`,`<html><head><meta charset="utf-8"><style>body{font-family:'Phetsarath OT','Noto Sans Lao'}table{border-collapse:collapse;width:100%;table-layout:fixed;font-size:8pt}th,td{border:1px solid #222;padding:4px;overflow-wrap:anywhere;word-break:break-word}</style></head><body>${officialPaper()}</body></html>`,'application/msword')};V('#lpr-xls').onclick=()=>{if(!data.length)return notify('Run report first',true);dl(`LVSP_${source}_report_${nameDate()}.xls`,`<html><head><meta charset="utf-8"></head><body>${tableHtml(data,chosen())}</body></html>`,'application/vnd.ms-excel')};V('#lpr-csv').onclick=()=>{if(!data.length)return notify('Run report first',true);const cols=chosen(),labels=source==='drug'?DRUG_COLS:TRADE_COLS;const cell=(v:any)=>'"'+String(v??'').replaceAll('"','""')+'"';dl(`LVSP_${source}_report_${nameDate()}.csv`,[cols.map(k=>cell(labels[k]||k)).join(','),...data.map(r=>cols.map(k=>cell(r[k])).join(','))].join('\r\n'),'text/csv;charset=utf-8')};configure(initialPreset);
}
